#!/usr/bin/env bash
# Acceptance checks for f0206. SEQUESTERED: never edit during execution.
# One `check "ACn: ..."` per Checked acceptance criterion, in the same order as the issue doc.
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)" # physical: tests/run strips the physical cwd
source "$(git -C "$HERE" rev-parse --show-toplevel)/z-nile/lib/ac.sh" # cds to the item's project home
# sequestered specs: here before `./zn done`, promoted to its project's tests/acceptance/f0206 after it
A="$HERE/acceptance"
[[ -d $A ]] || A="$PWD/tests/acceptance/f0206"

# Work outside `check` is limited to running a spec through `tests/run` (which AC_LIST=1 list mode refuses),
# `./zn members` and other cheap reads; everything else goes inside `check`.
check "AC1: a card's board shows three tabs (ALL-TIME, TODAY, THIS WEEK) stepped by W, Up and the left trigger back and S, Down and the right trigger forward, wrapping; a header naming the title's progress figure; rank, name, score, the figure and the revives used (a dash for none); LOADING, NO SCORES YET or SCORES UNAVAILABLE; the your-best line in the columns on the all-time tab; every text at least Card.MIN_TEXT pixels on every screen the carousel fits, the rows scrolling where they do not fit; and when the client asks again (REASK, or WAIT_RETRY after a wait)" lune run tests/run -- "$A/board.spec.luau"
check "AC2: the client reads an answer only for a known title, a board id and a status of ok, failed or wait, drops rows that make no sense, sorts and cuts to ten, reads junk revives as none, keeps a rank only when it is a row's and the best for the all-time board only, and never raises" lune run tests/run -- "$A/parse.spec.luau"
check "AC3: the server's read policy: a refresh only REFRESH after the board's last read, with a token of the read allowance (KEEP more for a board with rows) and the engine's budget holding COST above RESERVE; a forward inside the arcade's cache time after an answer that did not fail, with the player's best read at most once a BEST_GAP; else an answer from the held rows; ten minutes of asks on every board stay inside the allowance and the budget" lune run tests/run -- "$A/plan.spec.luau"
check "AC4: the server adapter on a stub server: every title's arcade boards opened by its HiscoreGames prefix and served on a relay of its own; asks on Remotes.Boards refreshed, forwarded or answered from the held rows as Board.plan says, the engine's StandardRead and OrderedList budgets read on each ask; the arcade's answers passed to the asker as (title, id, rows, rank, status, best) and held; nothing for a player who left, a fresh start for one who rejoins" lune run tests/run -- "$A/server.spec.luau"
check "AC5: the portal's relay and the arcade's real Boards together, flooded with asks on every board every second by 1, 4 and 20 players, stay inside the per-server sorted and standard read budgets and read no board twice inside REFRESH, still answering every player with the stored rows; a board kept in front shows a new run within two REFRESH periods" lune run tests/run -- "$A/budget.spec.luau"
check "AC6: the client adapter on a stub client: it starts the carousel, fills every card's Boards slot with three tabs, a header with the title's figure, ten row lines, a note and a best line laid out by Board.layout with Card's glyph width, every text at its one size (again on a resize); one tab for every card by a tap or the six keys of one binding between priorities 2000 and 3000, on the press, passed on while the player types; it asks for the front card's board when the front card or tab changes and again after REASK or WAIT_RETRY, and draws every answer on its own card" lune run tests/run -- "$A/client.spec.luau"
check "AC7: in the built portal place: ReplicatedStorage.Remotes.Boards, Board as a Logic leaf, Board's requires inside Logic, BoardRelay reaching the arcade's Boards and HiscoreGames and started once by the server's Main, BoardsView requiring CarouselView and started once by the client's Main, nothing a client reads requiring a server module; Board in portal's architecture map, and the arcade's E3 settled" lune run tests/run -- "$A/place.spec.luau"
check "AC8: Board has unit specs; Logic stays engine-free, every dependency is declared, and every feature has unit specs" bash -c 'test -d tests/unit/Board && lune run tests/run -- tests/meta/architecture.spec.luau'

finish
